document.addEventListener("DOMContentLoaded",()=>{const e=document.getElementById("search-toggle");if(!e)return;const t=()=>{const e=document.querySelector("pagefind-modal");e&&e.open()};e.addEventListener("click",t),window.addEventListener("keydown",n=>{if(n.ctrlKey||n.metaKey||n.altKey||n.shiftKey)return;if(n.key!=="/")return;const s=document.querySelector("pagefind-modal dialog");if(s&&s.open)return;if(document.activeElement!==e&&["TEXTAREA","SELECT"].includes(document.activeElement.tagName))return;if(document.activeElement.tagName==="INPUT"&&document.activeElement.type!=="checkbox")return;n.preventDefault(),t()},!0)})